// Hint system: InvisiClues-style graded hints, generated by the AI from the
// actual game code that governs the player's current situation.
//
// For the current room, its exits, and every object in view or carried, the
// routines that implement them (the JavaScript translation of the original ZIL)
// are collected together with the current values of the game variables those
// routines test. The model reads that code to work out what the player can do
// next, and answers at the requested level of detail.

import { chat } from './openrouter.js';
import { g, getProp, getPropAddr, propSize, get, inspect } from '../engine/runtime.js';
import { current } from '../engine/current.js';

const G = () => current.code;
import { actionContext } from './scene.js';
import { sceneText, currentScene } from './scene.js';

const DIRS = ['NORTH', 'NE', 'EAST', 'SE', 'SOUTH', 'SW', 'WEST', 'NW', 'UP', 'DOWN', 'IN', 'OUT'];
const MAX_ROUTINE = 3500;   // characters per routine
const MAX_CODE = 16000;     // characters of code per request

function routineSource(id) {
  const fn = G().ROUTINES[id - (G().ROUTINE_BASE ?? 0)];
  if (!fn) return null;
  let src = fn.toString();
  if (src.length > MAX_ROUTINE) src = src.slice(0, MAX_ROUTINE) + '\n  /* … truncated … */\n}';
  return src;
}

/** Collect the code and state relevant to the player's current situation. */
export function hintContext() {
  const sections = [];
  const seen = new Set();
  let budget = MAX_CODE;
  const add = (title, id) => {
    if (!id || seen.has(id) || budget <= 0) return;
    const src = routineSource(id);
    if (!src) return;
    seen.add(id);
    budget -= src.length;
    sections.push(`// ${title}\n${src}`);
  };

  const here = g.HERE;
  add(`Current location "${inspect.objectName(here)}": room handler`, getProp(here, G().P.ACTION));
  // Exits that are decided by code (e.g. doors, conditions).
  for (const d of DIRS) {
    const pt = getPropAddr(here, G().P[d]);
    if (pt && propSize(pt) === 3) add(`Exit ${d.toLowerCase()} from this location`, get(pt, 0));
  }
  // Pseudo-objects mentioned in the room description.
  const pp = getPropAddr(here, G().P.PSEUDO);
  if (pp) for (let i = 0; i < propSize(pp) / 4; i++) add(`"${inspect.pseudoWord(pp, i)}" in this location`, get(pp + 4 * i, 1));
  // Things in view and carried.
  const ctx = actionContext();
  for (const o of ctx.objects) {
    add(`${o.held ? 'Carried' : 'In view'}: "${o.name}"`, getProp(o.obj, G().P.ACTION));
  }

  // Current values of the game variables the collected code reads.
  const code = sections.join('\n\n');
  const names = [...new Set([...code.matchAll(/\bg\.([A-Z0-9_$]+)/g)].map((m) => m[1]))];
  const vars = names
    .filter((n) => !/^(PRSA|PRSO|PRSI|P_[A-Z_]+|L_PRS[AOI]|HERE|WINNER|C_ELAPSED)$/.test(n))
    .map((n) => {
      const v = g[n];
      const obj = typeof v === 'number' && v > 0 && v <= 255 && /OBJ|ROOM|LOC|PLACED|SPOT/.test(n) ? ` (${inspect.objectName(v)})` : '';
      return `${n} = ${JSON.stringify(v)}${obj}`;
    });
  return { code, vars };
}

const SYSTEM = (language) => `You are the hint system for ${current.meta.title.toUpperCase()}, the ${current.meta.year} Infocom text adventure, in the spirit of Infocom's InvisiClues booklets.

You receive the player's current situation and recent transcript, plus the ACTUAL GAME CODE that governs it: the JavaScript translation of the original ZIL routines for the current location, its exits, and every object in view or carried, together with the current values of the game variables those routines test. Read the code to work out what the player can do here, what is blocked, and what each object reacts to (look for the verbs a routine handles with isVerb(V.X, ...), the conditions on flags and variables, and what changes the score). You may also use your general knowledge of ${current.meta.title}, but the code and the current state are authoritative.

Decide the most useful next step for making progress or staying alive. If the transcript shows urgent trouble (hunger, thirst, exhaustion, sickness, a countdown, danger), address that first.

Answer at the requested HINT LEVEL:
- Level 1: a gentle nudge, ideally a question that points the player's attention somewhere. Do not name the solution.
- Level 2: a clearer direction: which object or place matters and roughly what kind of action.
- Level 3: the explicit solution, including the exact command(s) to type.

Rules:
- Write for the player, in ${language}, in 1–3 short sentences, in a light, friendly Infocom tone.
- Never mention code, routines, functions, variables, flags, numbers from the code, or "the game logic".
- Do not reveal places, objects or events the player has not encountered yet, except at level 3 when necessary for the next step.
- Output only the hint text.`;

/**
 * Ask the AI for a hint.
 * @param {object} p
 * @param {number} p.level 1..3
 */
export async function getHint({ apiKey, model, language, level, history, signal }) {
  const { code, vars } = hintContext();
  const transcript = history.slice(-8).map((h) =>
    `${h.input ? `PLAYER: ${h.input}\n` : ''}GAME: ${h.output.trim().slice(0, 1200)}`).join('\n---\n');
  const user =
    `HINT LEVEL: ${level}\n\n` +
    `SCORE: ${g.SCORE}${current.meta.maxScore ? ` of ${current.meta.maxScore}` : ""}. MOVES/TIME: ${g.MOVES}.\n\n` +
    `CURRENT SCENE:\n${sceneText(currentScene())}\n\n` +
    `RECENT TRANSCRIPT (oldest first):\n${transcript || '(none)'}\n\n` +
    `GAME VARIABLES USED BY THE CODE BELOW:\n${vars.join('\n') || '(none)'}\n\n` +
    `GAME CODE FOR THIS SITUATION:\n${code}`;
  const text = await chat({
    apiKey, model, signal, temperature: 0.3, maxTokens: 1200,
    messages: [{ role: 'system', content: SYSTEM(language), cache: true }, { role: 'user', content: user }],
  });
  const hint = text.trim().replace(/^["“]|["”]$/g, '');
  if (!hint) throw new Error('the model returned an empty answer');
  return hint;
}
